#include "stdlib/lapack/base/dlasyf.h"
#include "stdlib/lapack/base/shared.h"
#include <stdio.h>
#include <stdlib.h>

/**
* Main execution sequence.
*/
int main( void ) {
	const double diagonal[] = { 4.0, -3.0, 2.0, -1.0, 0.0, 6.0 };
	double *A;
	double *W;
	LAPACK_INT *IPIV;
	LAPACK_INT *KB;
	LAPACK_INT info;
	LAPACK_INT i;
	LAPACK_INT j;
	int result;

	A = (double *)malloc( 36 * sizeof( double ) );
	W = (double *)malloc( 18 * sizeof( double ) );
	IPIV = (LAPACK_INT *)malloc( 6 * sizeof( LAPACK_INT ) );
	KB = (LAPACK_INT *)malloc( sizeof( LAPACK_INT ) );
	result = EXIT_FAILURE;
	if ( A == NULL || W == NULL || IPIV == NULL || KB == NULL ) {
		fprintf( stderr, "Error allocating example buffers.\n" );
		goto cleanup;
	}
	for ( i = 0; i < 6; i++ ) {
		IPIV[ i ] = -99;
		for ( j = 0; j < 6; j++ ) {
			A[ (i*6)+j ] = ( i == j ) ? diagonal[ i ] : ( i > j ) ? 999.0 : 0.0;
		}
	}
	for ( i = 0; i < 18; i++ ) {
		W[ i ] = -9.0;
	}
	KB[ 0 ] = -9;
	info = API_SUFFIX(c_dlasyf)( LAPACK_ROW_MAJOR, LAPACK_UPPER_TRIANGLE, 6, 3, KB, A, 6, IPIV, W, 3 );
	if ( info != 5 || KB[ 0 ] != 2 || IPIV[ 4 ] != 5 || IPIV[ 5 ] != 6 ) {
		fprintf( stderr, "Unexpected partial factorization result.\n" );
		goto cleanup;
	}
	for ( i = 0; i < 4; i++ ) {
		if ( IPIV[ i ] != -99 ) {
			goto cleanup;
		}
	}
	for ( i = 0; i < 6; i++ ) {
		for ( j = 0; j < i; j++ ) {
			if ( A[ (i*6)+j ] != 999.0 ) {
				goto cleanup;
			}
		}
	}
	printf( "INFO: %d; KB: %d; produced pivots: %d, %d\n", (int)info, (int)KB[ 0 ], (int)IPIV[ 4 ], (int)IPIV[ 5 ] );

	// Reuse the allocations with disjoint leading views for a lower 2x2 block:
	A[ 0 ] = 0.0;
	A[ 1 ] = 999.0;
	A[ 2 ] = 4.0;
	A[ 3 ] = 0.0;
	info = API_SUFFIX(c_dlasyf_ndarray)( LAPACK_LOWER_TRIANGLE, 2, 2, KB, 0, A, 2, 1, 0, IPIV, 1, 0, W, 2, 1, 0 );
	if ( info != 0 || KB[ 0 ] != 2 || IPIV[ 0 ] != -2 || IPIV[ 1 ] != -2 || A[ 1 ] != 999.0 ) {
		fprintf( stderr, "Unexpected ordinary 2x2 pivot result.\n" );
		goto cleanup;
	}
	printf( "Ordinary 2x2 pivots: %d, %d\n", (int)IPIV[ 0 ], (int)IPIV[ 1 ] );
	result = EXIT_SUCCESS;

cleanup:
	free( A );
	free( W );
	free( IPIV );
	free( KB );
	return result;
}
